import { readFile } from 'node:fs/promises'

export const TERMINAL_STATUS_LIST = Object.freeze(['passed', 'partial', 'failed', 'blocked_env', 'succeeded', 'cancelled'])
export const TERMINAL_STATUSES = new Set(TERMINAL_STATUS_LIST)

export function isTerminalStatus(status) {
  return typeof status === 'string' && TERMINAL_STATUSES.has(status)
}

function assertRecord(record, label) {
  if (!record || typeof record !== 'object' || Array.isArray(record)) throw new Error(`Corrupt record at ${label}: expected a JSON object`)
  if (typeof record.taskId !== 'string' || record.taskId === '') throw new Error(`Corrupt record at ${label}: missing non-empty string taskId`)
  if (!Number.isInteger(record.trial) || record.trial < 1) throw new Error(`Corrupt record at ${label}: missing positive integer trial`)
  return record
}

export function parseRecords(text, source = 'runs.jsonl') {
  if (typeof text !== 'string') throw new TypeError('records text must be a string')
  const records = []
  text.split(/\r?\n/).forEach((line, index) => {
    if (line.trim() === '') return
    let parsed
    try { parsed = JSON.parse(line) } catch { throw new Error(`Corrupt JSONL in ${source} line ${index + 1}: not valid JSON`) }
    records.push(assertRecord(parsed, `${source} line ${index + 1}`))
  })
  return records
}

export async function readRecords(file) {
  let text
  try { text = await readFile(file, 'utf8') } catch (error) { if (error.code === 'ENOENT') return []; throw error }
  return parseRecords(text, file)
}

export function recordKey(taskId, trial) { return `${taskId}\u0000${trial}` }

export function selectPendingTrials(tasks, trials, records) {
  if (!Array.isArray(tasks)) throw new TypeError('tasks must be an array')
  if (!Number.isInteger(trials) || trials < 1) throw new TypeError('trials must be a positive integer')
  if (!Array.isArray(records)) throw new TypeError('records must be an array')
  const completed = new Set()
  records.forEach((record, index) => {
    const checked = assertRecord(record, `records[${index}]`)
    if (isTerminalStatus(checked.status)) completed.add(recordKey(checked.taskId, checked.trial))
  })
  const pending = []
  const planned = new Set()
  for (const task of tasks) {
    if (!task || typeof task.id !== 'string' || task.id === '') throw new Error('each task must expose a non-empty string id')
    for (let trial = 1; trial <= trials; trial++) {
      const key = recordKey(task.id, trial)
      if (completed.has(key) || planned.has(key)) continue
      planned.add(key)
      pending.push({ taskId: task.id, trial })
    }
  }
  return pending
}

