import test from 'node:test'
import assert from 'node:assert/strict'
import { mkdtemp, writeFile, rm } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { TERMINAL_STATUS_LIST, isTerminalStatus, parseRecords, readRecords, selectPendingTrials } from './resume.mjs'

const tasks = [{ id: 't1' }, { id: 't2' }]
const record = (taskId, trial, status) => ({ taskId, trial, status })

test('selectPendingTrials returns every plan slot in task order, trials starting at 1', () => {
  assert.deepEqual(selectPendingTrials(tasks, 2, []), [
    { taskId: 't1', trial: 1 },
    { taskId: 't1', trial: 2 },
    { taskId: 't2', trial: 1 },
    { taskId: 't2', trial: 2 },
  ])
})

test('the terminal status set is exactly the documented six', () => {
  assert.deepEqual(TERMINAL_STATUS_LIST, ['passed', 'partial', 'failed', 'blocked_env', 'succeeded', 'cancelled'])
  for (const status of TERMINAL_STATUS_LIST) assert.equal(isTerminalStatus(status), true)
  assert.equal(isTerminalStatus('running'), false)
  assert.equal(isTerminalStatus('pending'), false)
  assert.equal(isTerminalStatus(undefined), false)
})

test('every terminal status is skipped, including failed', () => {
  const records = TERMINAL_STATUS_LIST.map((status, index) => record('t1', index + 1, status))
  assert.deepEqual(selectPendingTrials(tasks, 1, records), [{ taskId: 't2', trial: 1 }])
})

test('running and pending trials are not skipped', () => {
  const records = [record('t1', 1, 'running'), record('t2', 1, 'pending')]
  assert.deepEqual(selectPendingTrials(tasks, 1, records), [
    { taskId: 't1', trial: 1 },
    { taskId: 't2', trial: 1 },
  ])
})

test('duplicate terminal records neither rerun nor duplicate a trial', () => {
  const records = [record('t1', 1, 'passed'), record('t1', 1, 'passed'), record('t1', 1, 'failed')]
  assert.deepEqual(selectPendingTrials(tasks, 2, records), [
    { taskId: 't1', trial: 2 },
    { taskId: 't2', trial: 1 },
    { taskId: 't2', trial: 2 },
  ])
})

test('statuses outside the terminal set stay pending', () => {
  const records = [record('t1', 1, 'timeout')]
  assert.deepEqual(selectPendingTrials(tasks, 1, records), [
    { taskId: 't1', trial: 1 },
    { taskId: 't2', trial: 1 },
  ])
})

test('parseRecords rejects corrupt JSONL with the offending line number', () => {
  assert.throws(
    () => parseRecords('{"taskId":"t1","trial":1,"status":"passed"}\nnot-json\n'),
    /Corrupt JSONL in runs\.jsonl line 2/,
  )
  assert.throws(() => parseRecords('{"taskId":"t1","status":"passed"}'), /missing positive integer trial/)
  assert.throws(() => parseRecords('[]'), /expected a JSON object/)
})

test('readRecords returns [] for a missing file and rejects corrupt JSONL', async () => {
  const dir = await mkdtemp(join(tmpdir(), 'pulse-resume-unit-'))
  try {
    assert.deepEqual(await readRecords(join(dir, 'missing.jsonl')), [])
    await writeFile(join(dir, 'runs.jsonl'), '{"taskId":"t1","trial":1,"status":"passed"}\n{oops\n')
    await assert.rejects(() => readRecords(join(dir, 'runs.jsonl')), /Corrupt JSONL/)
  } finally {
    await rm(dir, { recursive: true, force: true })
  }
})

