#!/usr/bin/env node
// Stage-4 check: reproduce an interrupted real run end to end with a local fake CLI.
// The runner under test is the real scripts/eval/run.mjs; the CLI it drives is
// scripts/eval/fake-cli.mjs, which never contacts a provider. Nothing is committed.
import { spawn } from 'node:child_process'
import { mkdtemp, mkdir, readFile, writeFile } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = resolve(dirname(fileURLToPath(import.meta.url)), '../..')
const taskId = process.argv[2] ?? 'files-02'
const trials = Number(process.argv[3] ?? '2')
