  schemaVersion: 1,
  taskId,
  category: 'file-organization',
  trial,
  model: { displayName: 'Fake Local Model', modelCode: 'fake-1', provider: 'local-fake' },
  status,
  runtimeStatus: status,
  taskOutcome: { status: status === 'succeeded' ? 'accepted' : 'rejected' },
  usage: { inputTokens: 10, outputTokens: 5, cachedInputTokens: 0, completeness: 'complete', providerCosts: [] },
  exitCode: status === 'succeeded' ? 0 : 1,
  elapsedMs: 5,
  cost: null,
  assistantText: '',
  traceSummary: { eventCounts: {}, eventCount: 0, hasGap: false, hasWaiting: false, textChars: 0, completeTraceAvailable: false },
  error: status === 'running' ? null : 'interrupted before completion',
  grading: { status: 'sandboxed-behavior-and-artifact-grader', score: 0, maxPoints: 1, passed: false, checks: [] },
  workspace: join(out, 'workspaces', taskId, `trial-${trial}`),
})
const seededText = `${[historicalRecord(1, 'failed'), historicalRecord(1, 'failed'), historicalRecord(2, 'running')].map((record) => JSON.stringify(record)).join('\n')}\n`
await writeFile(join(out, 'runs.jsonl'), seededText)

const preservedWorkspaceFile = join(out, 'workspaces', taskId, 'trial-1', 'interrupted-artifact.txt')
await mkdir(dirname(preservedWorkspaceFile), { recursive: true })
await writeFile(preservedWorkspaceFile, 'written by the interrupted run\n')
const preservedDataFile = join(out, 'pulse-data', taskId, 'trial-1', 'interrupted-state.json')
await mkdir(dirname(preservedDataFile), { recursive: true })
await writeFile(preservedDataFile, '{"phase":"interrupted"}\n')

