await writeFile(configPath, `${JSON.stringify({
  models: { 'fake-model': { displayName: 'Fake Local Model', provider: 'local-fake', modelCode: 'fake-1', maxContextTokens: 8000 } },
  providers: { 'local-fake': { provider: 'ollama', maxContextTokens: 8000 } },
}, null, 2)}\n`)

