  join(root, 'scripts/eval/run.mjs'),
  '--cli', join(root, 'scripts/eval/fake-cli.mjs'),
  '--config', configPath,
  '--model', 'Fake Local Model',
  '--task', taskId,
  '--trials', String(trials),
  '--out', out,
  '--resume',
  '--auto-approve',
  '--max-turns', '4',
  '--max-total-tokens', '100000',
], { env: { FAKE_CLI_LOG: logPath } })

console.log(`output directory: ${out}`)
check('run.mjs --resume exits 0', runner.code === 0, runner.stderr.trim().split('\n').slice(-3).join(' | '))
check('run.mjs reuses the existing output directory without an exists error', !/Output directory already exists/.test(runner.stderr))
check('run.mjs prints the resume header with existing and pending counts', /Resuming .*: 3 existing records, 1 pending trials/.test(runner.stdout), runner.stdout.split('\n').find((line) => line.startsWith('Resuming')) ?? 'header missing')
check('no provider credential or real model was involved', !/API_KEY|credential is unavailable|Real-provider|mock provider/i.test(`${runner.stdout}${runner.stderr}`))

const invocations = (await readFile(logPath, 'utf8')).trim().split('\n').filter(Boolean).map((line) => JSON.parse(line))
check('the fake CLI ran exactly once (only the unfinished trial)', invocations.length === 1, `invocations=${invocations.length}`)
check('the single CLI run targeted trial-2, never the terminal trial-1', invocations[0]?.cwd === join(out, 'workspaces', taskId, 'trial-2'), String(invocations[0]?.cwd))
check('the CLI was driven with the fake local model and JSONL output', invocations[0]?.model === 'Fake Local Model' && invocations[0]?.format === 'jsonl')

const afterText = await readFile(join(out, 'runs.jsonl'), 'utf8')
const afterLines = afterText.split('\n').filter(Boolean)
check('historical rows are byte-identical (nothing rewritten)', afterText.startsWith(seededText), `lines=${afterLines.length}`)
check('exactly one row was appended for the unfinished trial', afterLines.length === 4, `lines=${afterLines.length}`)
const counts = new Map()
for (const line of afterLines) { const record = JSON.parse(line); const key = `${record.taskId}/${record.trial}`; counts.set(key, (counts.get(key) ?? 0) + 1) }
check('no task/trial pair was rerun (duplicate terminal rows added nothing)', counts.get(`${taskId}/1`) === 2 && counts.get(`${taskId}/2`) === 1, JSON.stringify([...counts]))
const appended = JSON.parse(afterLines[afterLines.length - 1])
check('the appended record is a terminal success with complete usage', appended.trial === 2 && appended.status === 'succeeded' && appended.usage?.completeness === 'complete', `trial=${appended.trial} status=${appended.status}`)
check('the appended record carries the resume counters', appended.resume?.requested === true && appended.resume?.existingRecords === 3 && appended.resume?.pendingTrials === 1, JSON.stringify(appended.resume))

