check('the interrupted Pulse data directory was preserved', (await readFile(preservedDataFile, 'utf8')) === '{"phase":"interrupted"}\n')

const report = JSON.parse(await readFile(join(out, 'report.json'), 'utf8'))
check('report.json aggregates historical plus newly appended records', report.records.length === afterLines.length && report.records.length === 4, `records=${report.records.length} rows=${afterLines.length}`)
check('report.json keeps the historical rows in the aggregate', report.records.filter((record) => record.trial === 1).length === 2 && report.records.filter((record) => record.status === 'failed').length === 2, `trial1=${report.records.filter((record) => record.trial === 1).length}`)
check('report.json summarises the resumed run', report.completedRuns === 1 && report.tasksRun === 4 && report.budget.stoppedBeforeNextRun === false, `completed=${report.completedRuns} tasksRun=${report.tasksRun}`)
check('report.json records the resume counters', report.records.at(-1)?.resume?.pendingTrials === 1)

const headAfter = (await run('git', ['rev-parse', 'HEAD'])).stdout.trim()
const status = (await run('git', ['status', '--porcelain'])).stdout.trim()
check('no commit was created by the resumed run', headAfter === gitHeadBefore && headAfter !== '', `HEAD=${headAfter}`)
check('the run left no uncommitted changes inside the repository for its own output', !status.includes(out))
console.log('git status --porcelain:')
console.log(status === '' ? '(clean)' : status)

if (failures.length) {
  console.error(`\n${failures.length} check(s) failed: ${failures.join('; ')}`)
  process.exit(1)
}
console.log('\nall resume end-to-end checks passed')

