#!/usr/bin/env node
// Local fake Pulse CLI used only to exercise scripts/eval/run.mjs (including --resume) end to end.
// It never contacts a provider, so no real model is started. It accepts the same argv the runner
// passes to the real CLI, records its invocations, writes a local artifact, and prints the JSONL
// shape the real CLI prints (status / text / result).
import { appendFile, mkdir, writeFile } from 'node:fs/promises'
import { join } from 'node:path'

const args = process.argv.slice(2)
function option(name, fallback) { const index = args.indexOf(name); return index < 0 ? fallback : args[index + 1] }

const command = args[0]
if (command !== 'run') { console.error(`fake CLI only implements 'run' (got ${String(command)})`); process.exit(2) }

const cwd = option('--cwd', process.cwd())
const dataDir = option('--data-dir', undefined)
const prompt = String(args[1] ?? '').slice(0, 120)
const failed = process.env.FAKE_CLI_FAIL === '1'

if (process.env.FAKE_CLI_LOG) {
  await appendFile(process.env.FAKE_CLI_LOG, `${JSON.stringify({
    command,
    cwd,
    dataDir,
    prompt,
    model: option('--model', null),
    format: option('--format', null),
    approvalMode: option('--approval-mode', null),
    maxTurns: option('--max-turns', null),
    network: args.includes('--allow-network') ? 'allowed' : 'blocked',
  })}\n`)
}

await mkdir(cwd, { recursive: true })
if (dataDir) await mkdir(dataDir, { recursive: true })
await writeFile(join(cwd, 'fake-cli-artifact.txt'), `fake local run at ${new Date().toISOString()}\n`)
if (dataDir) await writeFile(join(dataDir, 'fake-cli-state.json'), `${JSON.stringify({ cwd, prompt })}\n`)

for (const line of [
  { type: 'status', data: 'fake-cli-start' },
  { type: 'text', data: 'fake CLI produced a local artifact' },
  {
    type: 'result',
    status: failed ? 'failed' : 'succeeded',
    taskOutcome: { status: failed ? 'rejected' : 'accepted' },
    usage: { inputTokens: 10, outputTokens: 5, cachedInputTokens: 0, completeness: 'complete', providerCosts: [] },
  },
]) console.log(JSON.stringify(line))

process.exit(failed ? 1 : 0)
